parameters.command:
cd /work/output/artifacts/skill-bpmn-expr-multiinstance-iterator/MultiInstanceIteratorBpmn
python3 << 'EOF'
import xml.etree.ElementTree as ET
ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}
tree = ET.parse('MultiInstanceIteratorBpmn.bpmn')
root = tree.getroot()

# 1. Root namespaces
print("1. root tag:", root.tag)

# collect all node ids (flowElements at any depth) and flow ids
def walk(el, depth=0):
    for child in el:
        tag = child.tag.split('}')[-1]
        if tag in ('startEvent','endEvent','task','subProcess','sequenceFlow','scriptTask','userTask','serviceTask'):
            yield child
        if tag == 'subProcess':
            yield from walk(child, depth+1)

nodes = []
flows = []
for proc in root.findall('bpmn:process', ns):
    for el in walk(proc):
        tag = el.tag.split('}')[-1]
        if tag == 'sequenceFlow':
            flows.append(el)
        else:
            nodes.append(el)

node_ids = {n.get('id') for n in nodes}
print("2. node ids:", node_ids)
print("   flow ids:", [f.get('id') for f in flows])

# shapes/edges
shapes = root.findall('.//bpmndi:BPMNShape', ns)
edges = root.findall('.//bpmndi:BPMNEdge', ns)
shape_refs = {s.get('bpmnElement') for s in shapes}
edge_refs = {e.get('bpmnElement') for e in edges}
print("3. shape refs:", shape_refs)
print("   edge refs:", edge_refs)

missing_shapes = node_ids - shape_refs
missing_edges = {f.get('id') for f in flows} - edge_refs
print("Missing shapes:", missing_shapes)
print("Missing edges:", missing_edges)

# sourceRef/targetRef resolve
all_ids = node_ids | {f.get('id') for f in flows}
for f in flows:
    src, tgt = f.get('sourceRef'), f.get('targetRef')
    if src not in all_ids or tgt not in all_ids:
        print("BAD FLOW REF:", f.get('id'), src, tgt)

print("All flow refs resolve OK" if all(f.get('sourceRef') in all_ids and f.get('targetRef') in all_ids for f in flows) else "BAD")
EOF

